import json, os
from collections import Counter

questions = []

# ══════════════════════════════════════════════════════════════════════════════
# DEVELOPMENT WITH AWS SERVICES — Difficulty 3-5 (advanced patterns)
# ══════════════════════════════════════════════════════════════════════════════
questions += [
  {"question_text":"A developer needs to implement a distributed lock to prevent multiple Lambda instances from processing the same resource simultaneously. What is the recommended approach?","options":["Use DynamoDB conditional writes with a TTL-based lock item that expires automatically","Use SQS FIFO queues with message group IDs to serialise access to the resource","Use Lambda reserved concurrency set to 1 to ensure only one instance runs at a time","Use ElastiCache Redis SETNX command with an expiration for the distributed lock"],"correct_answer":"Use DynamoDB conditional writes with a TTL-based lock item that expires automatically","explanation":"DynamoDB conditional PutItem (attribute_not_exists) creates a lock item atomically. TTL ensures the lock expires if the holder crashes. This is simpler than Redis for serverless architectures since DynamoDB is already serverless.","memory_technique":"DynamoDB lock = PutItem with attribute_not_exists condition + TTL. Atomic acquire, auto-expire on crash. Serverless-native distributed lock.","topic_area":"Development with AWS Services","difficulty_level":5,"it_context_mapping":"This is the distributed lock pattern — using conditional writes for mutual exclusion, similar to Redis Redlock but using DynamoDB."},
  {"question_text":"A developer's Lambda function needs to return a response to the caller immediately but continue processing in the background. How should they implement this?","options":["Use Lambda's built-in background processing by returning a response and continuing execution","Invoke a second Lambda function asynchronously before returning the response to the caller","Use Step Functions Express Workflow to return immediately and continue processing in subsequent states","Return the response and send remaining work to an SQS queue for a separate Lambda to process"],"correct_answer":"Return the response and send remaining work to an SQS queue for a separate Lambda to process","explanation":"Lambda freezes the execution environment after returning a response — background work won't complete reliably. Send remaining work to SQS (or invoke another Lambda async) before returning. The queue ensures the work is processed.","memory_technique":"Lambda freezes after response. No reliable background processing. Pattern: Return response + send work to SQS. Separate Lambda processes the queue.","topic_area":"Development with AWS Services","difficulty_level":4,"it_context_mapping":"This is the async task pattern — returning immediately to the caller while offloading work to a background processor via a queue."},
  {"question_text":"A developer is using DynamoDB single-table design and needs to query items across multiple entity types (orders and order items) for a given customer. What access pattern enables this?","options":["Use a Scan with a FilterExpression to find all items matching the customer ID","Use a Query with partition key = customer_id and sort key begins_with to retrieve related entities","Create separate GSIs for each entity type and query them independently","Use BatchGetItem to retrieve specific items by their full primary keys"],"correct_answer":"Use a Query with partition key = customer_id and sort key begins_with to retrieve related entities","explanation":"Single-table design uses composite sort keys (ORDER#123, ITEM#456). Query PK=customer_id returns all entities. Use begins_with(SK, 'ORDER#') to get only orders, or no SK condition to get everything for that customer.","memory_technique":"Single-table query: PK=customer_id, SK begins_with('ORDER#'). One query, multiple entity types. Hierarchical sort keys enable flexible access patterns.","topic_area":"Development with AWS Services","difficulty_level":4,"it_context_mapping":"Single-table design with composite sort keys is like a denormalised view — storing related entities together for efficient retrieval in a single query."},
  {"question_text":"A developer needs to implement a webhook receiver that must respond to the sender within 3 seconds (sender timeout) but the actual processing takes 30 seconds. What architecture handles this?","options":["Use API Gateway with a Lambda function that processes synchronously within the 3-second window","Use API Gateway with Lambda that immediately returns 200, sends the payload to SQS, and a separate Lambda processes it","Use API Gateway with a 30-second timeout configured to match the processing time","Use Application Load Balancer with a longer idle timeout to accommodate the 30-second processing"],"correct_answer":"Use API Gateway with Lambda that immediately returns 200, sends the payload to SQS, and a separate Lambda processes it","explanation":"The webhook receiver Lambda validates the payload, sends it to SQS, and immediately returns 200 (well within 3 seconds). A separate Lambda processes the message from SQS without time pressure. This decouples receipt from processing.","memory_technique":"Webhook pattern: Receive → validate → queue → return 200 immediately. Process async from queue. Decouple receipt (fast) from processing (slow).","topic_area":"Development with AWS Services","difficulty_level":3,"it_context_mapping":"This is the async webhook pattern — acknowledging receipt immediately and processing asynchronously, common in payment and notification systems."},
  {"question_text":"A developer needs to implement server-sent events (SSE) for real-time updates to a web client. Lambda functions are stateless and can't maintain long-lived connections. What AWS service enables this?","options":["API Gateway WebSocket API with a Lambda function that pushes updates to connected clients","AWS AppSync with GraphQL subscriptions that push updates over WebSocket connections","Amazon SNS with HTTP/S endpoint subscriptions that push to the client's callback URL","CloudWatch Events with a rule that triggers client notifications via Lambda"],"correct_answer":"AWS AppSync with GraphQL subscriptions that push updates over WebSocket connections","explanation":"AppSync subscriptions provide managed real-time updates over WebSocket. When data changes (via mutation), AppSync automatically pushes updates to all subscribed clients. No connection management needed — AppSync handles it.","memory_technique":"Real-time updates to clients = AppSync subscriptions. Managed WebSocket. Mutation triggers push to subscribers. No connection management code.","topic_area":"Development with AWS Services","difficulty_level":4,"it_context_mapping":"AppSync subscriptions are like Socket.io rooms — clients subscribe to topics and receive real-time pushes when data changes."},
  {"question_text":"A developer's application uses DynamoDB and needs to perform a complex aggregation (sum of order totals per customer per month). DynamoDB doesn't support aggregation queries. What is the best approach?","options":["Use DynamoDB Streams with Lambda to maintain pre-computed aggregates in a separate table","Perform a full table Scan and aggregate in application code on every request","Export DynamoDB data to S3 and use Athena for ad-hoc aggregation queries","Use DynamoDB PartiQL to write SQL-like aggregation queries directly"],"correct_answer":"Use DynamoDB Streams with Lambda to maintain pre-computed aggregates in a separate table","explanation":"DynamoDB Streams triggers Lambda on every write. The Lambda function updates pre-computed aggregates (monthly totals per customer) in a separate table or item. Reads are instant — just fetch the pre-computed value.","memory_technique":"DynamoDB aggregation = Pre-compute via Streams. Write triggers Lambda → update aggregate item. Reads are O(1). Materialised view pattern.","topic_area":"Development with AWS Services","difficulty_level":4,"it_context_mapping":"This is the materialised view pattern — pre-computing aggregates on write so reads are instant, common in event-sourced systems."},
  {"question_text":"A developer needs to implement a priority queue where high-priority messages are processed before low-priority ones. SQS doesn't natively support priority. What is the best approach?","options":["Use a single SQS FIFO queue with message group IDs representing priority levels","Create separate SQS queues per priority level and configure Lambda to poll high-priority first","Use SNS message attributes to tag priority and filter at the subscriber level","Use Step Functions to sort messages by priority before sending them to a single processing queue"],"correct_answer":"Create separate SQS queues per priority level and configure Lambda to poll high-priority first","explanation":"Use separate queues (high, medium, low priority). Configure Lambda event source mappings with different batch sizes or use a custom poller that checks high-priority first. This ensures high-priority messages are processed before low-priority ones.","memory_technique":"Priority queue on AWS = Multiple SQS queues by priority. Poll high first. Or: weighted processing (high gets more Lambda concurrency). SQS doesn't have native priority.","topic_area":"Development with AWS Services","difficulty_level":4,"it_context_mapping":"Multiple queues by priority is the standard pattern when the queue system doesn't support native priority — used in many production systems."},
]

